import LayoutContentStyle from '../../../../../components/utility/layoutContent.style'
import { PresetDetailsStyle, PresetViewStyle } from './index.style'
import { Button, Modal, Row, Tag } from 'antd'
import { useHistory } from 'react-router'
import CircularLoader from '../../../../../components/CircularLoader'
import { useEffect, useMemo, useState } from 'react'
import ViewPreset from '../../components/ViewPreset'
import { useDeletePreset, usePresetDetails } from '../../store/state/hooks/usePresetStore'
import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { PresetContextProvider } from '../../store/context'
import { formDataToView } from '../../helpers/converters'
import { showNotification } from '../../../../../components/ShowNotification'
import get from 'lodash/get'
import { createPresetRoute, editPresetRoute, presetListRoute } from '../../config/urls'

const PresetDetails = props => {
  const { presetId } = useMemo(() => props.match.params, [props.match.params])
  const history = useHistory()
  const [providerCode, setProviderCode] = useState('')
  const [{ getPresetDetailsData }, getPresetDetailsRequest] = usePresetDetails()
  const [loaderState] = useLoaderContextValue()
  const [deleteOpen, setDeleteOpen] = useState(false)
  const [, deletePresetRequest] = useDeletePreset()
  const isLoader = useMemo(() => {
    const { GET_PRESET_DETAILS_LOADER, DELETE_PRESET_LOADER } = loaderState
    return GET_PRESET_DETAILS_LOADER || DELETE_PRESET_LOADER
  }, [loaderState])
  const [{
    GET_PRESET_DETAILS_ERROR, DELETE_PRESET_ERROR,
    getPresetDetailsStatus, deletePresetStatus,
    getPresetDetailsErrorData, deletePresetErrorData
  }, dispatchError] = useErrorContextValue()

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    const provider = params.get('providerCode')
    if (provider) {
      setProviderCode(provider)
    }
  }, [setProviderCode])

  useEffect(() => {
    if (deletePresetStatus === 'success') {
      showNotification('success', 'Preset Deleted Successfully')
      dispatchError(resetError({
        deletePresetStatus: ''
      }))
      history.push(presetListRoute)
    } else if (DELETE_PRESET_ERROR && deletePresetStatus) {
      showNotification('error', get(deletePresetErrorData, 'message', 'failed to delete preset, try again'))
      dispatchError(resetError({
        deletePresetStatus: ''
      }))
    }
  }, [DELETE_PRESET_ERROR, deletePresetStatus,
    deletePresetErrorData, dispatchError, history])

  useEffect(() => {
    if (getPresetDetailsStatus === 'success') {
      dispatchError(resetError({
        getPresetDetailsStatus: ''
      }))
    } else if (GET_PRESET_DETAILS_ERROR && getPresetDetailsStatus) {
      showNotification('error', get(getPresetDetailsErrorData, 'message', 'failed to fetch preset details'))
      dispatchError(resetError({
        getPresetDetailsStatus: ''
      }))
    }
  }, [GET_PRESET_DETAILS_ERROR, getPresetDetailsStatus,
    getPresetDetailsErrorData, dispatchError])

  const data = useMemo(() => {
    return getPresetDetailsData?.preset_uuid && formDataToView(getPresetDetailsData)
  }, [getPresetDetailsData])
  const isActive = useMemo(() => {
    return getPresetDetailsData?.is_active === true
  }, [getPresetDetailsData])
  const handleDelete = () => {
    deletePresetRequest({
      uuid: presetId
    })
    setDeleteOpen(false)
  }
  useEffect(() => {
    getPresetDetailsRequest({
      uuid: presetId
    })
  }, [presetId, getPresetDetailsRequest])
  return (
    <LayoutContentStyle>
      <h2>Preset Details</h2>
      <CircularLoader isSpinning={isLoader}>
        <PresetDetailsStyle>
          <Row type='flex' justify='space-between'>
            <div><Button onClick={() => history.goBack()}>Back</Button></div>
            <div className='buttons'>
              {isActive && <Button type='danger' onClick={() => setDeleteOpen(true)}>Delete</Button>}
              <Button type='primary' onClick={() => history.push(createPresetRoute({ presetId, providerCode }))}>Duplicate</Button>
              {isActive && <Button type='primary' onClick={() => history.push(editPresetRoute(presetId))}>Edit</Button>}
            </div>
          </Row>
          <PresetViewStyle>
            {data?.formData && (isActive ? <Tag className='tag' color='green'>Active</Tag> : <Tag className='tag' color='red'>Not Active</Tag>)}
            {data?.formData && <ViewPreset presetData={data.formData} selectData={data.selectData} />}
          </PresetViewStyle>
          <Modal visible={deleteOpen} onCancel={() => setDeleteOpen(false)} onOk={handleDelete}>Are you sure you want to delete this preset?</Modal>
        </PresetDetailsStyle>
      </CircularLoader>
    </LayoutContentStyle>
  )
}

const WithProvider = (props) => {
  return (
    <PresetContextProvider>
      <PresetDetails {...props} />
    </PresetContextProvider>
  )
}

export default WithProvider
